def solve(strs):
    if not strs:
        return ""

    def common_prefix(a, b):
        min_len = min(len(a), len(b))
        for i in range(min_len):
            if a[i] != b[i]:
                return a[:i]
        return a[:min_len]

    prefix = strs[0]
    for s in strs[1:]:
        prefix = common_prefix(prefix, s)
        if not prefix:
            break
    return prefix
```

