def solve(strs):
    if not strs:
        return ""

    # Find the shortest string to limit comparisons
    min_len = min(len(s) for s in strs)
    result = ""

    for i in range(min_len):
        current_char = strs[0][i]
        for s in strs[1:]:
            if s[i] != current_char:
                return result
        result += current_char

    return result
```

