def solve(strs):
    if not strs:
        return ""

    def is_common_prefix(prefix, words):
        for word in words:
            if not word.startswith(prefix):
                return False
        return True

    left, right = 0, min(len(word) for word in strs) - 1
    while left <= right:
        mid = (left + right) // 2
        candidate = strs[0][:mid + 1]
        if is_common_prefix(candidate, strs):
            left = mid + 1
        else:
            right = mid - 1

    return strs[0][:left]
```

