def solve(strs):
    if not strs:
        return ""

    # Find the shortest string to minimize comparisons
    min_len = min(len(s) for s in strs)
    prefix = ""

    for i in range(min_len):
        # Check if all strings have the same character at position i
        if all(s[i] == strs[0][i] for s in strs):
            prefix += strs[0][i]
        else:
            break

    return prefix
```

