def solve(strs):
    if not strs:
        return ""

    # Check if all strings are non-empty
    if any(len(s) == 0 for s in strs):
        return ""

    # Get the first string to compare against
    prefix = strs[0]

    for s in strs[1:]:
        # Find the common prefix between prefix and s
        common = ""
        for ch1, ch2 in zip(prefix, s):
            if ch1 == ch2:
                common += ch1
            else:
                break
        prefix = common
        if not prefix:
            break

    return prefix
```

